// THE MESH GENERATOR THAT NEVER EXISTED.
//
//   node scripts/build-portrait-nodes.mjs <portrait> <out.json> [count]
//
// `public/v2/rudi-nodes.json` and its Miles counterpart were not generated by anything. Their own
// header says `"source": "docs/rudi-desktop.html (MESH)"`, and that is a hardcoded array of 900 x,y
// pairs baked into the approved reference by hand. So when the portrait changed there was nothing to
// re-run — and the points are face-anchored, which is easy to prove: plot them and you get a head, a
// neck and two shoulders. Over a different face they land as a constellation of somebody else.
//
// This is that missing step, written to reproduce what the reference did rather than to improve on it.
//
// ── WHAT THE ORIGINAL MESH ACTUALLY IS ──────────────────────────────────────────────────────────
//
// Measured off rudi-nodes.json rather than assumed:
//
//   900 points, all distinct, in the still's own 680×907 pixel space
//   nearest-neighbour spacing: median 4.5px, p25 2.2, p75 7.1, p95 10.4
//   vertical fifths, crown to hem:  214 / 218 / 139 / 193 / 136
//
// A median spacing of 4.5px across 900 points is not a scatter over a portrait — it is a set of
// points sitting ON the edges, tightly, with the flat field left empty. That is why the plot reads as
// a silhouette. So the generator samples the GRADIENT: where the image changes, points go; where it
// is flat, none do. The field excludes itself, with no threshold to tune, because a flat field has no
// gradient to be sampled by.
//
// ── AND WHY THE CANVAS NEVER SEES ANY OF THIS ───────────────────────────────────────────────────
//
// The engine reads a flat array and maps it through the same DX/DY/S it draws the portrait with. It
// has no opinion about where the points came from and this script does not import it. Nothing here
// runs at request time; the output is committed like the portrait it was made from.

import sharp from 'sharp'

const [, , SRC, OUT, COUNT = '900'] = process.argv
if (!SRC || !OUT) {
  console.error('usage: node scripts/build-portrait-nodes.mjs <portrait> <out.json> [count]')
  process.exit(1)
}
const N = Number(COUNT)

/**
 * A deterministic PRNG, seeded from nothing.
 *
 * The same portrait must produce the same mesh every time it is run: a regenerated nodes file that
 * differed by a few pixels would show up as a diff nobody can review and a constellation nobody
 * chose. Math.random() would make this file unreviewable in exactly that way.
 */
let seed = 0x2f6e2b1
const rnd = () => {
  seed ^= seed << 13; seed ^= seed >>> 17; seed ^= seed << 5
  return ((seed >>> 0) % 1e6) / 1e6
}

const img = sharp(SRC)
const { width: W, height: H } = await img.metadata()
const g = await img.clone().removeAlpha().greyscale().raw().toBuffer()
const at = (x, y) => g[y * W + x]

// Sobel. The magnitude only — a direction would let the sampler follow contours, which is a nicer
// picture and NOT what the reference is: its points sit on edges without tracing them, and a traced
// outline reads as a drawing of her rather than a network over her.
const mag = new Float32Array(W * H)
let peak = 0
for (let y = 1; y < H - 1; y++) {
  for (let x = 1; x < W - 1; x++) {
    const gx = -at(x - 1, y - 1) - 2 * at(x - 1, y) - at(x - 1, y + 1)
      + at(x + 1, y - 1) + 2 * at(x + 1, y) + at(x + 1, y + 1)
    const gy = -at(x - 1, y - 1) - 2 * at(x, y - 1) - at(x + 1, y - 1)
      + at(x - 1, y + 1) + 2 * at(x, y + 1) + at(x + 1, y + 1)
    const m = Math.hypot(gx, gy)
    mag[y * W + x] = m
    if (m > peak) peak = m
  }
}

// The weight a pixel carries. Squared, so a hard edge outruns a soft one by more than its contrast —
// this portrait is motion-blurred and almost everything has SOME gradient, which without this would
// spread the points across the whole face as a haze rather than gathering them where the shape is.
const weight = new Float32Array(W * H)
let total = 0
for (let i = 0; i < W * H; i++) {
  const t = mag[i] / peak
  const w = t < 0.06 ? 0 : t * t     // below 6% of peak is the field and the blur, and takes nothing
  weight[i] = w
  total += w
}

// Cumulative distribution, so a point can be drawn in one binary search rather than by rejection —
// with a blurred portrait most of the frame has weight near zero and rejection sampling would spin.
const cdf = new Float32Array(W * H)
let run = 0
for (let i = 0; i < W * H; i++) { run += weight[i]; cdf[i] = run }

const pick = () => {
  const r = rnd() * total
  let lo = 0, hi = W * H - 1
  while (lo < hi) { const mid = (lo + hi) >> 1; if (cdf[mid] < r) lo = mid + 1; else hi = mid }
  return [lo % W, (lo / W) | 0]
}

/**
 * Minimum spacing, enforced on a grid rather than against every point already placed.
 *
 * 2px, which is the original's floor — its p25 spacing is 2.2px, so points genuinely do sit almost on
 * top of each other and a Poisson-disc radius anywhere near the median would produce a sparser, more
 * even mesh that does not look like the reference at all. This exists only to stop exact duplicates
 * and pairs the engine would drop anyway: buildNet() ignores any edge closer than 4px (`dd > 16`).
 */
const MIN = 2
const cell = MIN
const grid = new Map()
const key = (x, y) => `${(x / cell) | 0},${(y / cell) | 0}`
const tooClose = (x, y) => {
  for (let a = -1; a <= 1; a++) for (let b = -1; b <= 1; b++) {
    for (const [px, py] of grid.get(`${((x / cell) | 0) + a},${((y / cell) | 0) + b}`) ?? []) {
      if ((px - x) ** 2 + (py - y) ** 2 < MIN * MIN) return true
    }
  }
  return false
}

const points = []
// Bounded rather than while(true): a portrait with almost no gradient — a flat colour, a failed
// export — would otherwise hang here instead of saying it could not find 900 edges to sit on.
for (let tries = 0; tries < N * 400 && points.length < N; tries++) {
  const [x, y] = pick()
  if (tooClose(x, y)) continue
  const k = key(x, y)
  const arr = grid.get(k)
  if (arr) arr.push([x, y]); else grid.set(k, [[x, y]])
  points.push([x, y])
}

if (points.length < N) {
  console.error(`only placed ${points.length} of ${N} — this portrait has too little edge to carry a mesh`)
  process.exit(1)
}

const xs = points.map((p) => p[0]), ys = points.map((p) => p[1])
const out = {
  source: `${SRC} (Sobel-weighted sample, scripts/build-portrait-nodes.mjs)`,
  format: 'flat [x, y] pairs in the still\'s own pixel space',
  count: points.length,
  extent: { x: [Math.min(...xs), Math.max(...xs)], y: [Math.min(...ys), Math.max(...ys)] },
  points,
}
await (await import('node:fs/promises')).writeFile(OUT, JSON.stringify(out))

// The same three numbers this was tuned against, printed so a regeneration can be compared to the
// original without opening the file.
const nn = points.map(([x, y]) => {
  let m = Infinity
  for (const [qx, qy] of points) {
    if (qx === x && qy === y) continue
    const d = (qx - x) ** 2 + (qy - y) ** 2
    if (d < m) m = d
  }
  return Math.sqrt(m)
}).sort((a, b) => a - b)
const q = (f) => nn[Math.floor(nn.length * f)].toFixed(1)
const fifths = [0, 0, 0, 0, 0]
const y0 = Math.min(...ys), y1 = Math.max(...ys)
for (const [, y] of points) fifths[Math.min(4, Math.floor(((y - y0) / (y1 - y0 + 1)) * 5))]++
console.log(`${points.length} points → ${OUT}`)
console.log(`  extent x ${out.extent.x.join('–')}  y ${out.extent.y.join('–')}`)
console.log(`  nearest-neighbour px: p25 ${q(0.25)}  median ${q(0.5)}  p75 ${q(0.75)}  p95 ${q(0.95)}`)
console.log(`  vertical fifths: ${fifths.join(' / ')}`)
